using Clipper2Lib;
using LibTessDotNet.Double;
using Microsoft.Xna.Framework;
using Sachssoft.Engine.Geometry;
using System;
using System.Collections.Generic;

namespace Sachssoft.Engine.Graphics.Rendering.Batches;

/// <summary>Builds non-overlapping stroke meshes and rectangle corner contours independently of GPU resources.</summary>
internal static class ShapeStrokeGeometry
{
    /// <summary>Specifies the number of line segments per rounded rectangle corner.</summary>
    internal const int CornerSegments = 8;

    /// <summary>Specifies the largest rectangle perimeter generated by this helper.</summary>
    internal const int RectangleCapacity = (CornerSegments + 1) * 4;

    /// <summary>Reuses the empty geometry result.</summary>
    private static readonly PolygonTriangulationResult Empty = new(Array.Empty<Vector2>(), Array.Empty<int>());

    /// <summary>Validates finite rectangle coordinates, including their calculated edges.</summary>
    /// <param name="bounds">The rectangle to validate.</param>
    internal static void ValidateBounds(Bounds2 bounds)
    {
        if (!float.IsFinite(bounds.X) || !float.IsFinite(bounds.Y) ||
            !float.IsFinite(bounds.Width) || !float.IsFinite(bounds.Height) ||
            !float.IsFinite(bounds.Right) || !float.IsFinite(bounds.Bottom))
            throw new ArgumentOutOfRangeException(nameof(bounds), "Rectangle coordinates must be finite.");
    }

    /// <summary>Validates a stroke width while retaining non-positive widths as no-ops.</summary>
    /// <param name="thickness">The width to validate.</param>
    internal static void ValidateThickness(float thickness)
    {
        if (!float.IsFinite(thickness)) throw new ArgumentOutOfRangeException(nameof(thickness));
    }

    /// <summary>Checks a finite point before it enters a geometry operation.</summary>
    /// <param name="point">The point to validate.</param>
    internal static void ValidatePoint(Vector2 point)
    {
        if (!float.IsFinite(point.X) || !float.IsFinite(point.Y))
            throw new ArgumentOutOfRangeException(nameof(point), "Shape coordinates must be finite.");
    }

    /// <summary>Writes a normalized clockwise rectangle contour, clamping corner size to half its smaller dimension.</summary>
    /// <param name="bounds">The rectangle bounds; reversed axes are normalized.</param>
    /// <param name="cornerType">The geometric corner treatment.</param>
    /// <param name="cornerSize">The radius or diagonal-cut extent in local coordinates.</param>
    /// <param name="destination">Storage for at least <see cref="RectangleCapacity"/> points.</param>
    /// <returns>The number of distinct perimeter points, or zero for an empty rectangle.</returns>
    internal static int RectangleContour(Bounds2 bounds, CornerType cornerType, float cornerSize, Span<Vector2> destination)
    {
        ValidateBounds(bounds);
        if (cornerType is not (CornerType.None or CornerType.Bevel or CornerType.Rounded))
            throw new ArgumentOutOfRangeException(nameof(cornerType));
        if (!float.IsFinite(cornerSize) || cornerSize < 0) throw new ArgumentOutOfRangeException(nameof(cornerSize));
        if (destination.Length < RectangleCapacity) throw new ArgumentException("Insufficient contour storage.", nameof(destination));
        float left = MathF.Min(bounds.Left, bounds.Right), right = MathF.Max(bounds.Left, bounds.Right);
        float top = MathF.Min(bounds.Top, bounds.Bottom), bottom = MathF.Max(bounds.Top, bounds.Bottom);
        float width = right - left, height = bottom - top;
        if (!float.IsFinite(width) || !float.IsFinite(height)) throw new ArgumentOutOfRangeException(nameof(bounds));
        if (width == 0 || height == 0) return 0;
        float radius = MathF.Min(cornerSize, MathF.Min(width, height) * 0.5f);
        int count = 0;
        if (cornerType == CornerType.None || radius == 0)
        {
            destination[0] = new(left, top); destination[1] = new(right, top);
            destination[2] = new(right, bottom); destination[3] = new(left, bottom);
            return 4;
        }
        if (cornerType == CornerType.Bevel)
        {
            Append(destination, ref count, new(left + radius, top));
            Append(destination, ref count, new(right - radius, top));
            Append(destination, ref count, new(right, top + radius));
            Append(destination, ref count, new(right, bottom - radius));
            Append(destination, ref count, new(right - radius, bottom));
            Append(destination, ref count, new(left + radius, bottom));
            Append(destination, ref count, new(left, bottom - radius));
            Append(destination, ref count, new(left, top + radius));
        }
        else
        {
            for (int corner = 0; corner < 4; corner++)
            {
                Vector2 center = corner switch
                {
                    0 => new(right - radius, top + radius),
                    1 => new(right - radius, bottom - radius),
                    2 => new(left + radius, bottom - radius),
                    _ => new(left + radius, top + radius)
                };
                for (int segment = 0; segment <= CornerSegments; segment++)
                {
                    float angle = (corner - 1 + segment / (float)CornerSegments) * MathF.PI * 0.5f;
                    Vector2 normal;
                    if (segment == 0 || segment == CornerSegments)
                    {
                        int axis = (corner + (segment == 0 ? 3 : 0)) % 4;
                        normal = axis switch { 0 => Vector2.UnitX, 1 => Vector2.UnitY, 2 => -Vector2.UnitX, _ => -Vector2.UnitY };
                    }
                    else normal = new(MathF.Cos(angle), MathF.Sin(angle));
                    Append(destination, ref count, center + normal * radius);
                }
            }
        }
        if (count > 1 && destination[count - 1] == destination[0]) count--;
        return count;
    }

    /// <summary>Writes a centered sharp rectangle ring without duplicate or overlapping corner coverage.</summary>
    /// <param name="bounds">The rectangle bounds.</param>
    /// <param name="thickness">The world-space stroke width.</param>
    /// <param name="vertices">Storage for eight vertices.</param>
    /// <param name="indices">Storage for twenty-four indices.</param>
    /// <param name="vertexCount">The number of generated vertices.</param>
    /// <returns>The number of generated indices.</returns>
    internal static int RectangleRing(Bounds2 bounds, float thickness, Span<Vector2> vertices, Span<int> indices, out int vertexCount)
    {
        ValidateBounds(bounds);
        ValidateThickness(thickness);
        if (vertices.Length < 8 || indices.Length < 24) throw new ArgumentException("Insufficient rectangle mesh storage.");
        vertexCount = 0;
        float left = MathF.Min(bounds.Left, bounds.Right), right = MathF.Max(bounds.Left, bounds.Right);
        float top = MathF.Min(bounds.Top, bounds.Bottom), bottom = MathF.Max(bounds.Top, bounds.Bottom);
        if (thickness <= 0 || left == right || top == bottom) return 0;
        float half = thickness * 0.5f;
        vertices[0] = new(left - half, top - half); vertices[1] = new(right + half, top - half);
        vertices[2] = new(right + half, bottom + half); vertices[3] = new(left - half, bottom + half);
        for (int i = 0; i < 4; i++) ValidatePoint(vertices[i]);
        if (thickness >= right - left || thickness >= bottom - top)
        {
            indices[0] = 0; indices[1] = 1; indices[2] = 3;
            indices[3] = 1; indices[4] = 2; indices[5] = 3;
            vertexCount = 4;
            return 6;
        }
        vertices[4] = new(left + half, top + half); vertices[5] = new(right - half, top + half);
        vertices[6] = new(right - half, bottom - half); vertices[7] = new(left + half, bottom - half);
        for (int side = 0; side < 4; side++)
        {
            int next = (side + 1) % 4, offset = side * 6;
            indices[offset] = side; indices[offset + 1] = next; indices[offset + 2] = next + 4;
            indices[offset + 3] = side; indices[offset + 4] = next + 4; indices[offset + 5] = side + 4;
        }
        vertexCount = 8;
        return 24;
    }

    /// <summary>Offsets and unions all centerlines before triangulation, preventing alpha overdraw at joins and crossings.</summary>
    /// <param name="contours">Finite transformed centerlines.</param>
    /// <param name="thickness">The stroke width in transformed coordinates.</param>
    /// <param name="join">The outer join treatment.</param>
    /// <param name="cap">The endpoint treatment for open paths.</param>
    /// <param name="closed">Whether the centerlines are closed loops.</param>
    /// <returns>A non-overlapping triangle mesh including any interior holes.</returns>
    internal static PolygonTriangulationResult Stroke(IReadOnlyList<IReadOnlyList<Vector2>> contours,
        float thickness, LineJoin join, LineCap cap, bool closed)
    {
        ValidateThickness(thickness);
        JoinType joins = join switch
        {
            LineJoin.Miter => JoinType.Miter, LineJoin.Bevel => JoinType.Bevel, LineJoin.Round => JoinType.Round,
            _ => throw new ArgumentOutOfRangeException(nameof(join))
        };
        EndType ends = cap switch
        {
            LineCap.Butt => EndType.Butt, LineCap.Square => EndType.Square, LineCap.Round => EndType.Round,
            _ => throw new ArgumentOutOfRangeException(nameof(cap))
        };
        var paths = new PathsD(contours.Count);
        foreach (var contour in contours)
        {
            var path = new PathD(contour.Count);
            foreach (Vector2 point in contour)
            {
                ValidatePoint(point);
                if (Math.Abs((double)point.X) > 1e12 || Math.Abs((double)point.Y) > 1e12)
                    throw new ArgumentOutOfRangeException(nameof(contours), "Stroke coordinates exceed the supported precision range.");
                if (path.Count == 0 || path[^1].x != point.X || path[^1].y != point.Y)
                    path.Add(new PointD(point.X, point.Y));
            }
            if (closed && path.Count > 1 && path[0] == path[^1]) path.RemoveAt(path.Count - 1);
            if (path.Count >= (closed ? 3 : 2)) paths.Add(path);
        }
        if (thickness <= 0 || paths.Count == 0) return Empty;
        if (thickness > 1e12f) throw new ArgumentOutOfRangeException(nameof(thickness));
        PathsD expanded = Clipper.InflatePaths(paths, thickness * 0.5, joins, closed ? EndType.Joined : ends,
            4, 6, Math.Min(thickness * 0.02, 0.1));
        PathsD united = Clipper.Union(expanded, new PathsD(), FillRule.NonZero, 6);
        var tess = new Tess();
        foreach (var path in united)
        {
            var points = new ContourVertex[path.Count];
            for (int i = 0; i < path.Count; i++) points[i].Position = new Vec3(path[i].x, path[i].y, 0);
            tess.AddContour(points, ContourOrientation.Original);
        }
        if (united.Count == 0) return Empty;
        tess.Tessellate(WindingRule.NonZero, ElementType.Polygons, 3);
        var vertices = new Vector2[tess.VertexCount];
        for (int i = 0; i < vertices.Length; i++)
        {
            vertices[i] = new((float)tess.Vertices[i].Position.X, (float)tess.Vertices[i].Position.Y);
            ValidatePoint(vertices[i]);
        }
        var indices = new List<int>(tess.ElementCount * 3);
        for (int i = 0; i < tess.ElementCount * 3; i += 3)
            if (tess.Elements[i] >= 0 && tess.Elements[i + 1] >= 0 && tess.Elements[i + 2] >= 0)
            {
                indices.Add(tess.Elements[i]); indices.Add(tess.Elements[i + 1]); indices.Add(tess.Elements[i + 2]);
            }
        return new PolygonTriangulationResult(vertices, indices);
    }

    /// <summary>Appends a perimeter point while suppressing consecutive duplicates at collapsed straight edges.</summary>
    /// <param name="destination">The reusable contour storage.</param>
    /// <param name="count">The number of points already written.</param>
    /// <param name="point">The next perimeter point.</param>
    private static void Append(Span<Vector2> destination, ref int count, Vector2 point)
    {
        if (count == 0 || destination[count - 1] != point) destination[count++] = point;
    }
}
